const featureWords:Record<string,string>={amount:'the amount spent',cost_per_unit:'the cost for the work done',image_count:'how many photos were attached'};
function plainReason(key:string,reason:string):string{
 if(key==='photo_similar'){
  let r=reason.replace(/ORB \+ RANSAC keypoint-confirmed \(≥\d+ good matches, ≥\d+% inlier ratio\)\./,'confirmed by closely comparing the two photos, not just a quick glance.');
  r=r.replace(/seen but not keypoint-confirmed/,'seen but not closely confirmed');
  return r;
 }
 if(key==='anomaly'){
  const m=reason.match(/largely due to its (\w+)\.$/);
  const word=m?featureWords[m[1]]||m[1]:'its overall details';
  return `This work looks unusual compared to similar works nearby, mainly because of ${word}.`;
 }
 return reason;
}
