// Backend origin. Same-origin ('') when the backend serves this build itself;
// set VITE_API_BASE (e.g. https://nazar-api.onrender.com) when the frontend is
// deployed separately, such as on Vercel.
const API_BASE=(import.meta.env.VITE_API_BASE||'').replace(/\/$/,'');
const apiUrl=(path:string)=>API_BASE+path;
const TOKEN_KEY='nazar_token';
let authToken:string|null=(()=>{try{return localStorage.getItem(TOKEN_KEY)}catch{return null}})();
function setToken(value:string|null){authToken=value;try{value?localStorage.setItem(TOKEN_KEY,value):localStorage.removeItem(TOKEN_KEY)}catch{}}
async function api<T>(url:string,options?:RequestInit):Promise<T>{
 const headers:Record<string,string>={...(options?.headers as Record<string,string>|undefined)};
 if(authToken)headers.Authorization=`Bearer ${authToken}`;
 const response=await fetch(apiUrl(url),{...options,headers});
 if(response.status===401&&!url.startsWith('/auth/')){setToken(null);location.reload();throw new Error('Session expired')}
 if(!response.ok){let detail='';try{const body=await response.json();detail=typeof body.detail==='string'?body.detail:JSON.stringify(body.detail)}catch{}throw new Error(detail||`Request failed (${response.status})`)}
 return response.json()}
